{
  "schemaVersion": "ride-output-v2.2.0",
  "label": {
    "text": "总距离 30.4 公里的平路骑行",
    "conclusionType": "fact",
    "claimIds": ["claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:metric.distanceM"]
  },
  "overallAssessment": {
    "text": "本次骑行总距离 30.4 公里，移动时长 1 小时 1 分钟，平均速度 29.29 km/h，平均心率 169 bpm，整体为一次强度较高的平路骑行。",
    "conclusionType": "fact",
    "claimIds": [
      "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:metric.distanceM",
      "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:timing.movingDurationS",
