      "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:heart_rate.mean"
    ]
  },
  "highlights": [
    {
      "text": "全程几乎全平路，地形分类覆盖率达到 100%，骑行节奏顺畅。",
      "conclusionType": "fact",
      "claimIds": [
        "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:terrain.trendFlatDistanceM",
        "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:terrain.classifiedCoverageRatio"
      ]
    },
    {
      "text": "巡航段最高平均速度达到 31.16 km/h，对应心率 180 bpm，是本次骑行的速度峰值。",
      "conclusionType": "fact",
      "claimIds": [
        "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-4-1461.speed.mean",
        "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-4-1461.heart_rate.mean"
      ]
    }
  ],
  "dimensions": [
    {
      "dimensionId": "pacingExecution",
      "assertions": [
        {
          "text": "本次骑行总距离 30.4 公里，移动时长 1 小时 1 分钟，总用时 1 小时 8 分钟，途中停车 2 次。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:metric.distanceM",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:timing.movingDurationS",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:metric.elapsedDurationS",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:stops.count"
          ]
        },
        {
          "text": "全程平均速度 29.29 km/h，速度变异系数 11%，首尾速度差 0.86 km/h，整体配速较为均匀。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:speed.mean",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:speed.coefficientOfVariation",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:speed.lastMinusFirst"
          ]
        },
        {
          "text": "巡航段速度在 28.74 km/h 至 31.16 km/h 之间波动，中段出现速度峰值，整体节奏控制得当。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-3-956.speed.mean",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-4-1461.speed.mean"
          ]
        },
        {
          "text": "地形分类覆盖率达到 100%，几乎全平路，无爬坡或下坡段。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:terrain.classifiedCoverageRatio",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:terrain.trendFlatDistanceM",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:terrain.trendClimbDistanceM",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:terrain.trendDescentDistanceM"
          ]
        }
      ]
    },
    {
      "dimensionId": "heartRateLoad",
      "assertions": [
        {
          "text": "平均心率 169 bpm，心率变异系数 5.6%，首尾心率差 9.3 bpm，心率整体处于较高水平。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:heart_rate.mean",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:heart_rate.coefficientOfVariation",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:heart_rate.lastMinusFirst"
          ]
        },
        {
          "text": "心率区间分布显示，Z4 区间占比 81%，Z5 区间占比 7%，高强度区间（Z4-Z5）合计占比 88%，本次骑行以高强度有氧为主。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:heartRate.zone.z4",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:heartRate.zone.z5",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:heartRate.zone.highIntensityCombined"
          ]
        },
        {
          "text": "巡航段心率在 158 bpm 至 180 bpm 之间波动，后半段心率维持在 170 bpm 以上，整体负荷较高。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-0-42.heart_rate.mean",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-4-1461.heart_rate.mean",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-7-2111.heart_rate.mean"
          ]
        },
        {
          "text": "速度与心率在同一时间窗口内的重合度达到 97%，两者变化趋势高度同步。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:relation.fixed.speed-heart_rate.aggregate"
          ]
        }
      ]
    },
    {
      "dimensionId": "cadenceStrategy",
      "assertions": [
        {
          "text": "平均踏频 83 rpm，踏频变异系数 19.8%，首尾踏频差 2.7 rpm，踏频整体处于中等水平。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:cadence.mean",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:cadence.coefficientOfVariation",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:cadence.lastMinusFirst"
          ]
        },
        {
          "text": "踏频区间分布显示，耐力区间占比 51%，高踏频区间占比 37%，零踏频区间占比 2%，整体以耐力踏频为主。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:cadence.zone.endurance",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:cadence.zone.high",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:cadence.zone.zero"
          ]
        },
        {
          "text": "巡航段踏频在 79 rpm 至 91 rpm 之间波动，部分高速段踏频略低，整体踏频选择较为灵活。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-1-393.cadence.mean",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-7-2111.cadence.mean"
          ]
        }
      ]
    },
    {
      "dimensionId": "crossSensorCoordination",
      "assertions": [
        {
          "text": "速度与心率在同一时间窗口内的重合度达到 97%，代表性窗口重合度最高为 100%，最低为 70%，整体同步性良好。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:relation.fixed.speed-heart_rate.aggregate",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:relation.fixed.speed-heart_rate.rep.6",
            "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:relation.fixed.speed-heart_rate.rep.29"
          ]
        }
      ]
    }
  ],
  "suggestions": [
    {
      "text": "本次骑行心率整体偏高，下次骑行可适当降低强度，将心率控制在 Z3 区间，以促进恢复。",
      "conclusionType": "suggestion",
      "claimIds": [
        "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:heart_rate.mean"
      ],
      "riskNote": "高强度骑行后需注意恢复，避免连续高强度训练。"
    },
    {
      "text": "巡航段踏频在高速时略有下降，下次骑行可尝试在高速段保持 85 rpm 以上的踏频，以提高踩踏效率。",
      "conclusionType": "suggestion",
      "claimIds": [
        "claim:upload-f95e988a-477e-4703-a2e7-0d1547fbe0b1:v2:segment.cruise.cruise-1-393.cadence.mean"
      ],
      "riskNote": "踏频调整需逐步适应，避免突然改变导致肌肉疲劳。"
    }
  ],
  "limitations": [
    "relation.fixed.speed-heart_rate.aggregate:AGGREGATED_FROM_119_WINDOWS",
    "power:SERIES_MISSING"
  ]
}
